package com.braseiro.dnd5e;

import org.json.JSONObject;
/** Single deterministic integration point for the 6.0 simulation layer. */
public final class WorldSixCoordinator {
    private final AppDb db;private final WorldHistoryEngine history;private final LivingSettlementEngine settlements;private final RumorNetworkEngine rumors;private final EmergentCampaignDirector director;private final CampaignLegacyEngine legacy;private final NpcVoiceDirector voices;private final ProceduralTacticalSceneGenerator tactical;
    public WorldSixCoordinator(AppDb database){db=database;history=new WorldHistoryEngine(db);settlements=new LivingSettlementEngine(db);rumors=new RumorNetworkEngine(db);director=new EmergentCampaignDirector(db);legacy=new CampaignLegacyEngine(db);voices=new NpcVoiceDirector(db);tactical=new ProceduralTacticalSceneGenerator(db);}
    public synchronized JSONObject tick(){/*BR_JSON_WRAP*/try{JSONObject o=new JSONObject();try{int day=Math.max(1,db.getSceneState().optInt("day_number",1));o.put("history",history.ingestCanonicalFacts()).put("settlements",settlements.simulateToDay(day)).put("rumors",rumors.update(day)).put("npc_contact_knowledge_spread",new AdventureContinuityEngine(db).propagateScheduledContacts(day)).put("director",director.refresh()).put("legacy",legacy.crystallize()).put("voices",voices.ensureScene());if(db.getCombatState().optInt("running",0)==1)o.put("tactical_scene",tactical.ensureForCurrentScene());}catch(Exception e){try{o.put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("WorldSixCoordinator","Falha tolerada na camada 6.0.",ignored);}}return o;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}
    public JSONObject context(){/*BR_JSON_WRAP*/try{JSONObject o=new JSONObject();try{o.put("campaign_director",director.context()).put("settlements",settlements.context()).put("rumors",rumors.context()).put("history",history.context()).put("legacy",legacy.context()).put("npc_voices",voices.context()).put("tactical_generation",tactical.context());}catch(Exception ignored){AppLog.ignored("WorldSixCoordinator","Falha tolerada na camada 6.0.",ignored);}return o;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}
}
